const MATERIALS = new Set(['rubber','metal','fuel']);
const SOCKETS = ['wheel-fl','wheel-fr','wheel-rl','wheel-rr','engine'];
const KEYS = {
 project:['schemaVersion','version','workspace','blocks','definitions','instances'],
 block:['x','y','z','material'], def:['id','name','responsibility','behavior','blocks'], inst:['id','definitionId','socket','rotation']
};
const clone = x => structuredClone(x);
const messages={'invalid wheel recipe':'轮子需要恰好 5 个橡胶方块','invalid wheel shape':'轮子要在同一层摆成五格十字','invalid thruster recipe':'推进器需要 2 个金属方块和 1 个虚拟燃料方块','invalid thruster shape':'沿 X 方向依次摆放：金属、金属、虚拟燃料','occupied socket':'该接口已有模块，请先拆下或换空接口','socket mismatch':'轮子要接轮子接口，推进器要接推进器接口','invalid coordinate':'方块超出工作台范围','duplicate block':'同一个格子不能重复放置','invalid instance':'实例或连接位置重复／无效','missing instance':'请先选中一个已装配模块'};
const bad = m => { throw new TypeError(messages[m] || '数据不符合工坊规则（'+m+'）'); };
const plain = x => x && typeof x==='object' && !Array.isArray(x) && Object.getPrototypeOf(x)===Object.prototype;
function exact(o, keys){ if(!plain(o) || Object.keys(o).some(k=>!keys.includes(k))) bad('invalid object'); }
function str(v,label,max=256){ if(typeof v!=='string'||!v.trim()||v.length>max) bad(`invalid ${label}`); return v; }
function coord(n,label){ if(!Number.isInteger(n)|| (label==='y' ? (n<0||n>4) : (n<-4||n>4))) bad('invalid coordinate'); return n; }
function block(b){ exact(b,KEYS.block); return {x:coord(b.x,'x'),y:coord(b.y,'y'),z:coord(b.z,'z'),material:(MATERIALS.has(b.material)?b.material:bad('invalid material'))}; }
function blocks(bs){ if(!Array.isArray(bs)||bs.length>64) bad('invalid blocks'); const out=bs.map(block), seen=new Set(); for(const b of out){const k=`${b.x},${b.y},${b.z}`;if(seen.has(k))bad('duplicate block');seen.add(k)} return out; }
function validateDefinition(d){ exact(d,KEYS.def); const out={id:str(d.id,'id'),name:str(d.name,'name'),responsibility:str(d.responsibility,'responsibility'),behavior:d.behavior,blocks:blocks(d.blocks)}; if(!['wheel','thruster'].includes(out.behavior))bad('invalid behavior'); checkRecipe(out.blocks,out.behavior); return out; }
function checkRecipe(bs,behavior){ const mats=bs.map(b=>b.material); if(behavior==='wheel'){if(bs.length!==5||mats.some(m=>m!=='rubber'))bad('invalid wheel recipe'); const z=bs[0].z; const xs=[...new Set(bs.map(b=>b.x))].sort((a,b)=>a-b),ys=[...new Set(bs.map(b=>b.y))].sort((a,b)=>a-b); if(xs.length!==3||ys.length!==3||!bs.some(b=>b.x===xs[1]&&b.y===ys[1])||bs.length!==5||bs.some(b=>b.z!==z))bad('invalid wheel shape'); const want=new Set([[0,0],[1,0],[-1,0],[0,1],[0,-1]].map(([x,y])=>`${x},${y}`)); const ox=xs[1],oy=ys[1]; if(new Set(bs.map(b=>`${b.x-ox},${b.y-oy}`)).size!==5||!bs.every(b=>want.has(`${b.x-ox},${b.y-oy}`)))bad('invalid wheel shape'); }
 else {if(bs.length!==3||bs.filter(b=>b.material==='metal').length!==2||bs.filter(b=>b.material==='fuel').length!==1||new Set(bs.map(b=>`${b.y},${b.z}`)).size!==1){bad('invalid thruster recipe')} const sorted=[...bs].sort((a,b)=>a.x-b.x); if(!(sorted[0].material==='metal'&&sorted[1].material==='metal'&&sorted[2].material==='fuel'&&sorted[1].x===sorted[0].x+1&&sorted[2].x===sorted[1].x+1))bad('invalid thruster shape');}}
export function recipe(behavior){ if(behavior==='wheel') return [{x:1,y:1,z:0,material:'rubber'},{x:2,y:1,z:0,material:'rubber'},{x:0,y:1,z:0,material:'rubber'},{x:1,y:2,z:0,material:'rubber'},{x:1,y:0,z:0,material:'rubber'}]; if(behavior==='thruster')return [{x:0,y:0,z:0,material:'metal'},{x:1,y:0,z:0,material:'metal'},{x:2,y:0,z:0,material:'fuel'}]; bad('invalid behavior'); }
export function emptyProject(workspace=''){ return {schemaVersion:1,version:'mc-workshop-1',workspace:str(workspace,'workspace'),blocks:[],definitions:[],instances:[]}; }
export function validateProject(raw){ exact(raw,KEYS.project); if(raw.schemaVersion!==1||raw.version!=='mc-workshop-1')bad('invalid schema'); if(!Array.isArray(raw.definitions)||raw.definitions.length>16)bad('invalid definitions'); const p={schemaVersion:1,version:'mc-workshop-1',workspace:str(raw.workspace,'workspace'),blocks:blocks(raw.blocks),definitions:raw.definitions.map(validateDefinition),instances:[]}; if(p.definitions.length>16||!Array.isArray(raw.definitions))bad('invalid definitions'); if(!Array.isArray(raw.instances)||raw.instances.length>5)bad('invalid instances'); const ids=new Set(p.definitions.map(d=>d.id)); if(ids.size!==p.definitions.length)bad('duplicate definition'); const iids=new Set(), sockets=new Set(); for(const i of raw.instances){exact(i,KEYS.inst); const q={id:str(i.id,'id'),definitionId:str(i.definitionId,'definitionId'),socket:i.socket,rotation:i.rotation}; if(sockets.has(q.socket)||iids.has(q.id)||!ids.has(q.definitionId)||!SOCKETS.includes(q.socket)||![0,180].includes(q.rotation))bad('invalid instance'); if((q.socket==='engine')!==(p.definitions.find(d=>d.id===q.definitionId).behavior==='thruster'))bad('socket mismatch'); iids.add(q.id);sockets.add(q.socket);p.instances.push(q);} return clone(p); }
export function saveDefinition(project,input){const p=validateProject(project); const d=validateDefinition({...input,blocks:input.blocks}); if(p.definitions.some(x=>x.id===d.id))bad('duplicate definition'); if(p.definitions.length>=16)bad('too many definitions'); const min=Object.fromEntries(['x','y','z'].map(k=>[k,Math.min(...d.blocks.map(b=>b[k]))]));d.blocks=d.blocks.map(b=>({...b,x:b.x-min.x,y:b.y-min.y,z:b.z-min.z})); p.definitions.push(d); return p;}
export function placeInstance(project,{id,definitionId,socket,rotation=0}){const p=validateProject(project); if(p.instances.some(i=>i.socket===socket))bad('occupied socket'); return validateProject({...p,instances:[...p.instances,{id,definitionId,socket,rotation}]});}
export function moveInstance(project,id,socket){const p=validateProject(project), i=p.instances.find(x=>x.id===id);if(!i)bad('missing instance'); return placeReplace(p,{...i,socket});}
function placeReplace(p,ni){return validateProject({...p,instances:p.instances.map(i=>i.id===ni.id?ni:i)});}
export function rotateInstance(project,id){const p=validateProject(project),i=p.instances.find(x=>x.id===id);if(!i)bad('missing instance');return placeReplace(p,{...i,rotation:i.rotation===0?180:0});}
export function removeInstance(project,id){const p=validateProject(project);return {...p,instances:p.instances.filter(i=>i.id!==id)};}
export function assemblyIssues(project){const p=validateProject(project), issues=[]; for(const s of SOCKETS)if(!p.instances.some(i=>i.socket===s))issues.push(`缺少${s}`); for(const i of p.instances){const d=p.definitions.find(x=>x.id===i.definitionId);if((i.socket==='engine'&&d.behavior!=='thruster')||(i.socket!=='engine'&&d.behavior!=='wheel'))issues.push(`插槽${i.socket}行为错误`)} return issues;}
export function parseProject(json,workspace){if(typeof json!=='string'||json.length>100*1024)bad('invalid json'); const p=validateProject(JSON.parse(json)); if(workspace!==undefined)p.workspace=str(workspace,'workspace'); return p;}
export function createHistory(initial){let past=[validateProject(initial)],pos=0; return {get:()=>clone(past[pos]),apply(n){const valid=validateProject(n);past.splice(pos+1);past.push(valid);if(past.length>50)past.shift();else pos++;pos=Math.min(pos,past.length-1)},undo(){if(pos)pos--;return clone(past[pos])},redo(){if(pos<past.length-1)pos++;return clone(past[pos])}};}
